function spansOf(blocks) {
  return Core__Array.reduce(blocks, [], (function (acc, param) {
                var to = param[1];
                var from = param[0];
                var match = acc.at(-1);
                if (match !== undefined && match[1] === from) {
                  return Belt_Array.concatMany([
                              acc.slice(0, acc.length - 1 | 0),
                              [[
                                  match[0],
                                  to
                                ]]
                            ]);
                }
                return Belt_Array.concatMany([
                            acc,
                            [[
                                from,
                                to
                              ]]
                          ]);
              }));
}

function courtDayOf(o) {
  var match = o.price;
  var high = match[1];
  var low = match[0];
  return {
          id: "court-" + o.venue.id.replace("loc-", "") + "-" + o.date,
          localDate: o.date,
          link: Js_null.fromOption(o.link),
          location: o.venue,
          intervals: windows(spansOf(o.blocks)),
          hourly: o.blocks.flatMap(function (param) {
                var outdoor = param[3];
                var indoor = param[2];
                return Belt_Array.range(param[0], param[1] - 1 | 0).map(function (hour) {
                            return {
                                    hour: hour,
                                    indoorCount: indoor,
                                    outdoorCount: outdoor,
                                    priceMin: low,
                                    priceMax: high
                                  };
                          });
              })
        };
}

var courtDays = openings.map(courtDayOf);

function courtRows(days) {
  return days.map(function (d) {
              return {
                      id: d.id,
                      localDate: d.localDate,
                      link: Caml_option.null_to_opt(d.link),
                      locationId: Core__Option.map(Caml_option.null_to_opt(d.location), (function (l) {
                              return l.id;
                            })),
                      locationName: Core__Option.map(Caml_option.null_to_opt(d.location), (function (l) {
                              return l.name;
                            })),
                      intervals: d.intervals.map(function (iv) {
                            return [
                                    iv.startHour,
                                    iv.endHour
                                  ];
                          }),
                      hourlyStats: d.hourly.map(function (h) {
                            return {
                                    hour: h.hour,
                                    indoorCount: h.indoorCount,
                                    outdoorCount: h.outdoorCount,
                                    priceMin: Caml_option.null_to_opt(h.priceMin),
                                    priceMax: Caml_option.null_to_opt(h.priceMax)
                                  };
                          })
                    };
            });
}

function courtsOn(date) {
  return PkEventsAvailabilityDay.courtAvailabilityForDate(courtRows(courtDays), date, "Court");
}

function courtGroupsOn(date) {
  return TimeWindow.groupContiguousPseudoEventBands(TimeWindow.groupCourtAvailabilityIntoPseudoEventBands(courtsOn(date)));
}

function intentsOf(intervals) {
  return intervals.map(function (iv, i) {
              return {
                      id: i,
                      start: iv.startHour,
                      end: iv.endHour
                    };
            });
}

function viewerIntentsOn(date) {
  return Core__Option.getOr(Core__Option.map(viewerAvailability.find(function (d) {
                      return d.localDate === date;
                    }), (function (d) {
                    return intentsOf(d.intervals);
                  })), []);
}

function slotPlayersOn(date) {
  return playerAvailability.filter(function (d) {
                return d.localDate === date;
              }).map(function (d) {
              var name = Core__Option.getOr(Core__Option.flatMap(Caml_option.null_to_opt(d.user), (function (u) {
                          return Caml_option.null_to_opt(u.lineUsername);
                        })), "?");
              return {
                      id: d.id,
                      name: name,
                      initials: name.slice(0, 2).toUpperCase(),
                      intents: intentsOf(d.intervals)
                    };
            });
}

function demandOn(date) {
  return playerAvailability.filter(function (d) {
                return d.localDate === date;
              }).map(function (d, i) {
              return {
                      id: i,
                      intents: intentsOf(d.intervals)
                    };
            });
}

function existingEventsOn(date) {
  return viewerEvents.filter(function (e) {
                return tokyoDay(new Date(e.startDate)) === date;
              }).map(function (e) {
              return {
                      id: e.id,
                      title: e.title,
                      startHour: TimeWindow.hourInTimeZone(new Date(e.startDate), "Asia/Tokyo"),
                      endHour: TimeWindow.hourInTimeZone(new Date(e.endDate), "Asia/Tokyo")
                    };
            });
}

function daysFrom(start, count) {
  return Belt_Array.makeBy(count, (function (i) {
                return tokyoDay(new Date(new Date(start + "T12:00:00+09:00").getTime() + i * 86400000));
              }));
}

function byDate(dates, f) {
  return Js_dict.fromArray(dates.map(function (date) {
                  return [
                          date,
                          f(date)
                        ];
                }));
}

